# ! [feature (const_generics)] # ! [feature (const_evaluatable_checked)] use std :: sync :: Arc ; pub enum Predicate < const EXPRESSION : bool > { } pub trait Satisfied { } impl Satisfied for Predicate < true > { } pub trait Depth { const DEPTH : usize ; } # [doc = " Make it impossible to have cyclic Arc references."] pub struct AcArc < T : Depth , const D : usize > { # [allow (dead_code)] inner : Arc < T > , } impl < T : Depth , const D : usize > AcArc < T , D > { pub fn new (item : T) -> Self where Predicate < { T :: DEPTH <= D } > : Satisfied , { Self { inner : Arc :: new (item) , } } } impl Depth for u8 { const DEPTH : usize = 0 ; } fn main () { let arc : AcArc < u8 , 0 > = AcArc :: new (42_u8) ; println ! ("Hello, world!") ; }